using System;using System.Collections.Generic;using System.Globalization;using ForteMove.Models.Common;using ForteMove.Models.Drivers;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Admin.Drivers{public partial class CreateDriver:AdminPage{protected void Page_Load(object sender,EventArgs e){if(!IsPostBack)txtEmployeeNumber.Text=ServiceFactory.CreateDriverService().GetCreationOptions().SuggestedEmployeeNumber;}protected void btnSave_Click(object sender,EventArgs e){IList<ValidationError> binding=new List<ValidationError>();DriverLicenceCode lc;DriverAvailabilityStatus av;var result=ServiceFactory.CreateDriverService().CreateDriver(new CreateDriverRequest{EmployeeNumber=txtEmployeeNumber.Text,FirstName=txtFirstName.Text,LastName=txtLastName.Text,Email=txtEmail.Text,PhoneNumber=txtPhone.Text,DateOfBirth=ParseDate(txtDateOfBirth.Text,"DateOfBirth",binding),AvailabilityStatus=Enum.TryParse(ddlAvailability.SelectedValue,out av)?av:(DriverAvailabilityStatus?)null,TemporaryPassword=txtTemporaryPassword.Text,LicenceNumber=txtLicenceNumber.Text,LicenceCode=Enum.TryParse(ddlLicenceCode.SelectedValue,out lc)?lc:(DriverLicenceCode?)null,LicenceExpiryDate=ParseDate(txtLicenceExpiry.Text,"LicenceExpiryDate",binding),PrdpNumber=txtPrdpNumber.Text,PrdpExpiryDate=ParseDate(txtPrdpExpiry.Text,"PrdpExpiryDate",binding)},CurrentPrincipalContext.UserAccountId);if(binding.Count>0){Show(binding);return;}if(!result.Succeeded){Show(result.Errors);return;}string message="Driver "+result.Value.EmployeeNumber+" was created successfully."+(result.HasWarnings?" "+string.Join(" ",result.Warnings):string.Empty);FlashMessageStore.Put(Session,message,result.HasWarnings);Response.Redirect(ResolveUrl("~/Admin/Drivers/DriverDetails.aspx?id="+result.Value.DriverProfileId),true);}private static DateTime? ParseDate(string text,string field,IList<ValidationError> errors){if(string.IsNullOrWhiteSpace(text))return null;DateTime v;if(DateTime.TryParseExact(text,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out v))return v;errors.Add(new ValidationError(field,"Enter a valid date."));return null;}private void Show(IEnumerable<ValidationError> e){pnlErrors.Visible=true;rptErrors.DataSource=e;rptErrors.DataBind();}}}
